import React, { useEffect, useState } from 'react';
import { api } from './api';
import './App.css';

function App() {
  const [products, setProducts] = useState([]);

  useEffect(() => {
    api.getProducts().then(data => setProducts(data));
  }, []);

  return (
    <div className="store">
      <h1>Мой IT-Магазин</h1>
      <div className="grid">
        {products.map(p => (
          <div key={p.id} className="card">
            <div className="category">{p.category}</div>
            <h3>{p.name}</h3>
            <p>{p.description}</p>
            <div className="price">{p.price} ₽</div>
            <div className="stock">На складе: {p.stock} шт.</div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;
